) as incoming(id,name,organizer,kind,official_url,topics,priority,enabled,check_interval_hours,evidence_url,notes)
where not exists (
  select 1 from discovery_targets t
  where t.id=incoming.id or rtrim(t.official_url,'/')=rtrim(incoming.official_url,'/')
)
and not exists (
  select 1 from official_sources s
  where rtrim(s.base_url,'/')=rtrim(incoming.official_url,'/')
     or exists (select 1 from unnest(s.listing_urls) u where rtrim(u,'/')=rtrim(incoming.official_url,'/'))
)
on conflict (id) do nothing;
